/* Auto-generated: the Investment Planner tool as a single string.
   Do not hand-edit. To change the tool, edit its .html and regenerate. */
export default "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Investment for Daughter</title>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.0/chart.umd.min.js\"></script>\n<style>\n  * { box-sizing: border-box; }\n  body {\n    margin: 0; background: #FAF6EF; color: #2E3A46;\n    font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;\n    padding: 24px 16px 60px;\n  }\n  .container { max-width: 640px; margin: 0 auto; }\n  .eyebrow { font-size: 13px; letter-spacing: 0.08em; color: #E8A33D; font-weight: 600; margin-bottom: 8px; }\n  h1 { font-family: Georgia, 'Times New Roman', serif; font-size: 30px; font-weight: 600; margin: 0 0 8px; color: #0F3D3E; line-height: 1.15; }\n  h2 { font-family: Georgia, 'Times New Roman', serif; font-size: 19px; color: #0F3D3E; margin: 0 0 12px; }\n  .sub { font-size: 15px; color: #5C6B73; margin: 0 0 24px; line-height: 1.5; }\n  .panel { background: #fff; border-radius: 14px; padding: 20px 20px 24px; margin-bottom: 16px; box-shadow: 0 1px 3px rgba(15,61,62,0.08); border: 1px solid #EFE9DC; }\n  .row { margin-bottom: 20px; }\n  .label { display: block; font-size: 13px; font-weight: 600; color: #5C6B73; margin-bottom: 8px; text-transform: uppercase; letter-spacing: 0.04em; }\n  .slider-row { display: flex; align-items: center; gap: 12px; }\n  input[type=\"range\"] { flex: 1; accent-color: #0F3D3E; }\n  .age-value { font-family: Georgia, serif; font-size: 18px; font-weight: 600; color: #0F3D3E; min-width: 56px; text-align: right; }\n  .pill-group { display: flex; flex-wrap: wrap; gap: 8px; }\n  .pill { padding: 8px 14px; border-radius: 999px; border: 1px solid #DCD3C1; background: #fff; font-size: 13.5px; cursor: pointer; color: #5C6B73; font-weight: 500; }\n  .pill.active { background: #0F3D3E; color: #fff; border-color: #0F3D3E; }\n  .hint { font-size: 13px; color: #8A7B68; margin-top: 6px; line-height: 1.4; }\n  input[type=\"number\"] { padding: 8px 10px; border-radius: 8px; border: 1px solid #DCD3C1; font-size: 14px; font-family: inherit; }\n  .num-wide { width: 160px; font-size: 16px; font-weight: 600; }\n  .rupee { font-size: 16px; font-weight: 600; color: #0F3D3E; }\n  .result-banner { display: flex; align-items: center; gap: 16px; background: #0F3D3E; color: #fff; border-radius: 14px; padding: 18px 20px; margin-bottom: 16px; }\n  .horizon-badge { font-family: Georgia, serif; font-size: 36px; font-weight: 700; background: #E8A33D; color: #0F3D3E; width: 68px; height: 68px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }\n  .horizon-label { font-size: 13px; opacity: 0.85; text-transform: uppercase; letter-spacing: 0.04em; }\n  .horizon-sub { font-size: 14.5px; margin-top: 4px; line-height: 1.4; }\n  .note-box { background: #FCF3E3; border: 1px solid #F0DCB4; border-radius: 10px; padding: 10px 14px; font-size: 13.5px; color: #7A5A1F; margin-bottom: 16px; }\n  .warn-box { background: #FFF7E6; border: 1px solid #F0DCA0; color: #7A5A1F; font-size: 13px; padding: 10px 14px; border-radius: 10px; line-height: 1.5; margin-bottom: 14px; }\n  .alloc-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n  .alloc-card { background: #FAF8F2; border-radius: 10px; padding: 14px 14px 16px; border-top: 3px solid #0F3D3E; }\n  .alloc-label { font-size: 12.5px; font-weight: 700; color: #5C6B73; text-transform: uppercase; letter-spacing: 0.03em; }\n  .alloc-amount { font-family: Georgia, serif; font-size: 20px; font-weight: 700; color: #2E3A46; margin: 4px 0; }\n  .alloc-sub { font-size: 12px; color: #8A7B68; }\n  .invested-tag { font-size: 12px; color: #A69B87; margin: 4px 0 2px; }\n  .total-corpus { font-family: Georgia, serif; font-size: 34px; font-weight: 700; color: #0F3D3E; margin: 8px 0; }\n  .compare-row { display: flex; align-items: center; gap: 14px; margin: 6px 0 10px; flex-wrap: wrap; }\n  .compare-card { flex: 1 1 160px; }\n  .compare-label { font-size: 12.5px; font-weight: 600; color: #8A7B68; text-transform: uppercase; letter-spacing: 0.03em; margin-bottom: 4px; }\n  .compare-amount-muted { font-family: Georgia, serif; font-size: 26px; font-weight: 600; color: #8A7B68; }\n  .compare-amount { font-family: Georgia, serif; font-size: 30px; font-weight: 700; color: #0F3D3E; }\n  .compare-arrow { font-size: 22px; color: #E8A33D; font-weight: 700; }\n  .gain-badge { display: inline-block; background: #EAF2EA; color: #2F5233; font-size: 13.5px; font-weight: 600; padding: 6px 12px; border-radius: 999px; margin-bottom: 6px; }\n  .inflation-badge { background: #FCEFEF; color: #8A3B3B; font-size: 13.5px; font-weight: 500; padding: 10px 14px; border-radius: 10px; line-height: 1.5; }\n  .footer { font-size: 12px; color: #A69B87; text-align: center; margin-top: 8px; line-height: 1.5; }\n  .divider { margin-top: 18px; padding-top: 16px; border-top: 1px solid #EFE9DC; }\n  canvas { max-width: 100%; }\n</style>\n</head>\n<body>\n<div class=\"container\">\n  <div class=\"eyebrow\">\u092c\u0947\u091f\u0940 \u00b7 \u0928\u093f\u0935\u0947\u0936 \u00b7 \u092f\u094b\u091c\u0928\u093e</div>\n  <h1>Investment for Daughter</h1>\n  <p class=\"sub\">Set her age and the goal. The plan \u2014 and how it should shift as the goal gets closer \u2014 follows.</p>\n\n  <div class=\"panel\">\n    <div class=\"row\">\n      <label class=\"label\">Current age</label>\n      <div class=\"slider-row\">\n        <input type=\"range\" id=\"age\" min=\"0\" max=\"20\" value=\"13\">\n        <span class=\"age-value\" id=\"ageVal\">13 yrs</span>\n      </div>\n    </div>\n\n    <div class=\"row\">\n      <label class=\"label\">Goal</label>\n      <div class=\"pill-group\" id=\"purposeGroup\">\n        <button class=\"pill active\" data-purpose=\"education\">Higher Education</button>\n        <button class=\"pill\" data-purpose=\"marriage\">Marriage</button>\n        <button class=\"pill\" data-purpose=\"general\">General Corpus</button>\n        <button class=\"pill\" data-purpose=\"custom\">Custom age</button>\n      </div>\n      <div id=\"customTargetRow\" style=\"margin-top:10px; display:none;\">\n        <input type=\"number\" id=\"customTarget\" value=\"18\" style=\"width:90px;\">\n        <span class=\"hint\"> target age for goal</span>\n      </div>\n      <div class=\"hint\" id=\"purposeNote\">Corpus typically needed at 18, sometimes earlier for foreign admissions.</div>\n    </div>\n\n    <div class=\"row\">\n      <label class=\"label\">Investment style</label>\n      <div class=\"pill-group\">\n        <button class=\"pill active\" id=\"modeSip\" data-mode=\"sip\">Recurring (SIP)</button>\n        <button class=\"pill\" id=\"modeLumpsum\" data-mode=\"lumpsum\">Lump Sum</button>\n      </div>\n    </div>\n\n    <div class=\"row\" id=\"frequencyRow\">\n      <label class=\"label\">Contribution frequency</label>\n      <div class=\"pill-group\" id=\"freqGroup\">\n        <button class=\"pill active\" data-freq=\"monthly\" data-ppy=\"12\">Monthly</button>\n        <button class=\"pill\" data-freq=\"quarterly\" data-ppy=\"4\">Quarterly</button>\n        <button class=\"pill\" data-freq=\"halfyearly\" data-ppy=\"2\">Half-Yearly</button>\n        <button class=\"pill\" data-freq=\"yearly\" data-ppy=\"1\">Yearly</button>\n      </div>\n    </div>\n\n    <div class=\"row\">\n      <label class=\"label\" id=\"amountLabel\">Monthly amount</label>\n      <div class=\"slider-row\">\n        <span class=\"rupee\">\u20b9</span>\n        <input type=\"number\" id=\"amount\" class=\"num-wide\" value=\"100000\">\n        <span class=\"hint\" id=\"amountSuffix\">/ month</span>\n      </div>\n      <div class=\"hint\" id=\"lumpsumNote\" style=\"display:none;\">SSY and PPF each accept up to \u20b91.5L per year \u2014 a large lump sum beyond that can't all go into these tax-free instruments in one shot; the excess is routed here to equity/debt instead. Depositing the capped portion again each following year (if you have more lump sums later) would need to be done separately.</div>\n    </div>\n\n    <div class=\"row\">\n      <label class=\"label\">Expected inflation</label>\n      <div class=\"slider-row\">\n        <input type=\"range\" id=\"inflation\" min=\"0\" max=\"12\" step=\"0.5\" value=\"6\">\n        <span class=\"age-value\" id=\"inflationVal\">6%</span>\n      </div>\n      <div class=\"hint\">India's long-run retail inflation has typically run 5-7%. This only affects the \"today's money\" figures below \u2014 it doesn't change your actual investment returns.</div>\n    </div>\n\n    <div class=\"row\">\n      <label class=\"label\">Your income tax slab (for debt fund gains)</label>\n      <div class=\"pill-group\" id=\"slabGroup\">\n        <button class=\"pill\" data-slab=\"5\">5%</button>\n        <button class=\"pill\" data-slab=\"20\">20%</button>\n        <button class=\"pill active\" data-slab=\"30\">30%</button>\n      </div>\n      <div class=\"hint\">Debt fund gains are taxed entirely at your income slab rate under today's rules (Section 50AA), regardless of holding period. Equity fund LTCG is taxed separately at 12.5% above \u20b91.25L/year \u2014 that part isn't affected by your slab.</div>\n    </div>\n  </div>\n\n  <div class=\"result-banner\">\n    <div class=\"horizon-badge\" id=\"horizonBadge\">5</div>\n    <div>\n      <div class=\"horizon-label\">years to goal</div>\n      <div class=\"horizon-sub\" id=\"horizonSub\"></div>\n    </div>\n  </div>\n\n  <div class=\"panel\">\n    <h2 id=\"allocTitle\">Per monthly allocation</h2>\n    <div class=\"note-box\" id=\"ssyNote\" style=\"display:none;\">Sukanya Samriddhi Yojana isn't available \u2014 she's past the under-10 opening window. PPF fills that role below.</div>\n    <div class=\"alloc-grid\" id=\"allocGrid\"></div>\n  </div>\n\n  <div class=\"panel\">\n    <h2>Glide path to <span id=\"targetAgeLabel1\"></span></h2>\n    <p class=\"hint\">Equity share steps down automatically as the goal nears \u2014 this is the shift you make yourself each year, not a one-time choice.</p>\n    <canvas id=\"glideChart\" height=\"200\"></canvas>\n  </div>\n\n  <div class=\"panel\">\n    <h2>Invested vs. grown, by age <span id=\"targetAgeLabel2\"></span></h2>\n    <p class=\"hint\">Illustrative only \u2014 assumes the amount held flat and today's allocation split held flat (in practice the equity share falls per the glide path above, so real returns will be somewhat lower than this simple estimate near the goal).</p>\n    <div class=\"compare-row\">\n      <div class=\"compare-card\">\n        <div class=\"compare-label\">You'll have invested</div>\n        <div class=\"compare-amount-muted\" id=\"totalInvestedOut\"></div>\n      </div>\n      <div class=\"compare-arrow\">\u2192</div>\n      <div class=\"compare-card\">\n        <div class=\"compare-label\">It should become</div>\n        <div class=\"compare-amount\" id=\"totalGrownOut\"></div>\n      </div>\n    </div>\n    <div class=\"gain-badge\" id=\"gainBadgeOut\"></div>\n    <div class=\"alloc-grid\" id=\"bucketCompareGrid\" style=\"margin-top:14px;\"></div>\n  </div>\n\n  <div class=\"panel\">\n    <h2>What that corpus is really worth</h2>\n    <p class=\"hint\" id=\"inflationExplainer\"></p>\n    <div class=\"warn-box\">Don't compare this figure to \"total invested\" above \u2014 that sum is raw nominal rupees paid in at different times, with no time-value adjustment. Deflating the whole final corpus by the full horizon's inflation is too harsh on money you contributed recently, so this number can look smaller than what you put in even when the plan is genuinely beating inflation. The section below is the correct check for that.</div>\n    <div class=\"compare-row\">\n      <div class=\"compare-card\">\n        <div class=\"compare-label\">Nominal corpus</div>\n        <div class=\"compare-amount-muted\" id=\"nominalCorpusOut\"></div>\n      </div>\n      <div class=\"compare-arrow\">\u2192</div>\n      <div class=\"compare-card\">\n        <div class=\"compare-label\">Worth in today's \u20b9</div>\n        <div class=\"compare-amount\" id=\"realValueOut\"></div>\n      </div>\n    </div>\n    <div class=\"inflation-badge\" id=\"inflationBadgeOut\"></div>\n\n    <div class=\"divider\">\n      <div class=\"label\">The correct check: real gain, net of just keeping pace with inflation</div>\n      <p class=\"hint\" id=\"realGainExplainer\"></p>\n      <div class=\"compare-row\">\n        <div class=\"compare-card\">\n          <div class=\"compare-label\">Just tracking inflation</div>\n          <div class=\"compare-amount-muted\" id=\"inflationOnlyOut\"></div>\n        </div>\n        <div class=\"compare-arrow\">\u2192</div>\n        <div class=\"compare-card\">\n          <div class=\"compare-label\">Your actual plan</div>\n          <div class=\"compare-amount\" id=\"actualPlanOut\"></div>\n        </div>\n      </div>\n      <div class=\"gain-badge\" id=\"realGainBadgeOut\"></div>\n    </div>\n  </div>\n\n  <div class=\"panel\">\n    <h2>Tax on exit, at today's rates</h2>\n    <p class=\"hint\">Assumes today's tax rules hold at maturity, treating this as the only relevant income. SSY and PPF stay fully tax-free (EEE status). Equity fund gains are taxed as LTCG at 12.5%, but only above a \u20b91.25L/year exemption. Debt fund gains get no such exemption \u2014 every rupee of gain is taxed at your slab rate.</p>\n    <div class=\"alloc-grid\" id=\"taxGrid\"></div>\n    <div class=\"divider\">\n      <div class=\"compare-row\">\n        <div class=\"compare-card\">\n          <div class=\"compare-label\">Before tax</div>\n          <div class=\"compare-amount-muted\" id=\"beforeTaxOut\"></div>\n        </div>\n        <div class=\"compare-arrow\">\u2192</div>\n        <div class=\"compare-card\">\n          <div class=\"compare-label\" id=\"afterTaxLabel\"></div>\n          <div class=\"compare-amount\" id=\"afterTaxOut\"></div>\n        </div>\n      </div>\n    </div>\n    <div class=\"divider\">\n      <div class=\"label\">After-tax, in today's purchasing power</div>\n      <div class=\"total-corpus\" id=\"afterTaxRealOut\"></div>\n      <div class=\"hint\">This is the realistic number to plan the actual goal against \u2014 after tax, and expressed in today's \u20b9.</div>\n    </div>\n  </div>\n\n  <div class=\"footer\">Assumptions are illustrative estimates, not guarantees \u2014 actual returns on equity and debt instruments vary. Not financial advice.</div>\n</div>\n\n<script>\nconst PURPOSES = {\n  education: { targetAge: 18, note: \"Corpus typically needed at 18, sometimes earlier for foreign admissions.\" },\n  marriage: { targetAge: 21, note: \"SSY itself matures for withdrawal purposes at 21, aligning naturally.\" },\n  general: { targetAge: 25, note: \"No fixed trigger \u2014 longest runway, can stay growth-heavy longest.\" },\n};\n\nlet state = {\n  age: 13, purposeId: \"education\", useCustom: false, customTarget: 18,\n  mode: \"sip\", frequency: \"monthly\", periodsPerYear: 12,\n  amount: 100000, inflation: 6, slabRate: 30,\n};\n\nfunction fvPeriodicSIP(periodicAmount, annualRate, periodsPerYear, years) {\n  if (periodicAmount <= 0 || years <= 0) return 0;\n  const r = annualRate / periodsPerYear;\n  const n = periodsPerYear * years;\n  return periodicAmount * ((Math.pow(1 + r, n) - 1) / r) * (1 + r);\n}\nfunction fvLumpSum(principal, annualRate, years) {\n  if (principal <= 0 || years <= 0) return principal;\n  return principal * Math.pow(1 + annualRate, years);\n}\nfunction buildGlidePath(horizon) {\n  const points = [];\n  for (let y = 0; y <= horizon; y++) {\n    const remaining = horizon - y;\n    let equity;\n    if (remaining >= 5) equity = 65;\n    else if (remaining >= 3) equity = 50;\n    else if (remaining >= 2) equity = 35;\n    else if (remaining >= 1) equity = 20;\n    else equity = 10;\n    points.push({ year: y, equity, debt: 100 - equity });\n  }\n  return points;\n}\nfunction fmt(n) { return \"\u20b9\" + Math.round(n).toLocaleString(\"en-IN\"); }\n\nfunction computeStrategy() {\n  const { age, purposeId, useCustom, customTarget, mode, frequency, periodsPerYear, amount, inflation, slabRate } = state;\n  const targetAge = useCustom ? customTarget : PURPOSES[purposeId].targetAge;\n  const horizon = Math.max(targetAge - age, 0);\n  const ssyEligible = age < 10;\n  const glide = buildGlidePath(horizon);\n  const currentSplit = glide[0] || { equity: 20, debt: 80 };\n\n  let ssyPeriodic=0, ppfPeriodic=0, equityPeriodic=0, debtPeriodic=0;\n  let ssyInvested=0, ppfInvested=0, equityInvested=0, debtInvested=0;\n  let ssyFV=0, ppfFV=0, equityFV=0, debtFV=0;\n\n  if (mode === \"lumpsum\") {\n    const ssyLump = ssyEligible ? Math.min(150000, amount) : 0;\n    let remaining = amount - ssyLump;\n    const ppfLump = Math.min(150000, remaining);\n    remaining -= ppfLump;\n    const equityLump = remaining * (currentSplit.equity / 100);\n    const debtLump = remaining * (currentSplit.debt / 100);\n    ssyInvested = ssyLump; ppfInvested = ppfLump; equityInvested = equityLump; debtInvested = debtLump;\n    ssyFV = fvLumpSum(ssyLump, 0.082, horizon);\n    ppfFV = fvLumpSum(ppfLump, 0.071, horizon);\n    equityFV = fvLumpSum(equityLump, 0.12, horizon);\n    debtFV = fvLumpSum(debtLump, 0.075, horizon);\n  } else {\n    const annualAmount = amount * periodsPerYear;\n    const ssyAnnual = ssyEligible ? Math.min(150000, annualAmount) : 0;\n    let remainingAnnual = annualAmount - ssyAnnual;\n    const ppfAnnual = Math.min(150000, remainingAnnual);\n    remainingAnnual -= ppfAnnual;\n    const equityAnnual = remainingAnnual * (currentSplit.equity / 100);\n    const debtAnnual = remainingAnnual * (currentSplit.debt / 100);\n    ssyPeriodic = ssyAnnual / periodsPerYear;\n    ppfPeriodic = ppfAnnual / periodsPerYear;\n    equityPeriodic = equityAnnual / periodsPerYear;\n    debtPeriodic = debtAnnual / periodsPerYear;\n    ssyInvested = ssyAnnual * horizon;\n    ppfInvested = ppfAnnual * horizon;\n    equityInvested = equityAnnual * horizon;\n    debtInvested = debtAnnual * horizon;\n    ssyFV = fvPeriodicSIP(ssyPeriodic, 0.082, periodsPerYear, horizon);\n    ppfFV = fvPeriodicSIP(ppfPeriodic, 0.071, periodsPerYear, horizon);\n    equityFV = fvPeriodicSIP(equityPeriodic, 0.12, periodsPerYear, horizon);\n    debtFV = fvPeriodicSIP(debtPeriodic, 0.075, periodsPerYear, horizon);\n  }\n\n  const totalInvested = equityInvested + debtInvested + ppfInvested + ssyInvested;\n  const total = equityFV + debtFV + ppfFV + ssyFV;\n\n  const inflationRate = inflation / 100;\n  const monthlyInflationRate = Math.pow(1 + inflationRate, 1/12) - 1;\n  const monthsToGoal = horizon * 12;\n  const realValue = horizon > 0 ? total / Math.pow(1 + monthlyInflationRate, monthsToGoal) : total;\n  const inflationMultiple = Math.pow(1 + monthlyInflationRate, monthsToGoal);\n\n  let inflationOnlyFV;\n  if (mode === \"lumpsum\") {\n    inflationOnlyFV = fvLumpSum(totalInvested, inflationRate, horizon);\n  } else {\n    const totalPeriodic = ssyPeriodic + ppfPeriodic + equityPeriodic + debtPeriodic;\n    inflationOnlyFV = fvPeriodicSIP(totalPeriodic, inflationRate, periodsPerYear, horizon);\n  }\n  const realGain = total - inflationOnlyFV;\n\n  const equityGain = Math.max(0, equityFV - equityInvested);\n  const equityTaxableGain = Math.max(0, equityGain - 125000);\n  const equityTax = equityTaxableGain * 0.125;\n  const debtGain = Math.max(0, debtFV - debtInvested);\n  const debtTax = debtGain * (slabRate / 100);\n  const totalTax = equityTax + debtTax;\n  const afterTaxTotal = total - totalTax;\n  const afterTaxRealValue = horizon > 0 ? afterTaxTotal / Math.pow(1 + monthlyInflationRate, monthsToGoal) : afterTaxTotal;\n\n  return {\n    targetAge, horizon, ssyEligible, glide, currentSplit,\n    ssyPeriodic, ppfPeriodic, equityPeriodic, debtPeriodic,\n    ssyInvested, ppfInvested, equityInvested, debtInvested, totalInvested,\n    ssyFV, ppfFV, equityFV, debtFV, total,\n    realValue, inflationMultiple, purchasingPowerLoss: total - realValue,\n    inflationOnlyFV, realGain,\n    equityGain, equityTax, debtGain, debtTax, totalTax, afterTaxTotal, afterTaxRealValue,\n  };\n}\n\nlet glideChartInstance = null;\n\nfunction render() {\n  const s = computeStrategy();\n  const mode = state.mode;\n\n  document.getElementById('ageVal').textContent = state.age + ' yrs';\n  document.getElementById('horizonBadge').textContent = s.horizon;\n  document.getElementById('horizonSub').textContent =\n    s.horizon <= 2 ? \"Short runway \u2014 capital protection matters more than growth now.\" :\n    s.horizon <= 5 ? \"Medium runway \u2014 balanced, with a deliberate glide toward safety.\" :\n    \"Long runway \u2014 growth can lead, safety builds in as the date nears.\";\n  document.getElementById('targetAgeLabel1').textContent = s.targetAge;\n  document.getElementById('targetAgeLabel2').textContent = s.targetAge;\n\n  document.getElementById('ssyNote').style.display = (!s.ssyEligible && state.age >= 10) ? 'block' : 'none';\n\n  const freqLabelMap = { monthly: 'Monthly', quarterly: 'Quarterly', halfyearly: 'Half-Yearly', yearly: 'Yearly' };\n  document.getElementById('allocTitle').textContent = mode === 'lumpsum' ? 'Lump sum split' : `Per ${freqLabelMap[state.frequency].toLowerCase()} allocation`;\n\n  const allocGrid = document.getElementById('allocGrid');\n  allocGrid.innerHTML = '';\n  const buckets = [\n    { label: 'SSY', sub: 'Govt-backed, 8.2%, tax-free', amt: mode === 'lumpsum' ? s.ssyInvested : s.ssyPeriodic, color: '#E8A33D', show: s.ssyEligible },\n    { label: 'PPF', sub: 'Govt-backed, 7.1%, tax-free', amt: mode === 'lumpsum' ? s.ppfInvested : s.ppfPeriodic, color: '#4E6C50', show: true },\n    { label: 'Debt funds', sub: '~7.5% target, stability layer', amt: mode === 'lumpsum' ? s.debtInvested : s.debtPeriodic, color: '#7A6C5D', show: true },\n    { label: 'Equity index', sub: `~12% target, ${s.currentSplit.equity}% of growth pool`, amt: mode === 'lumpsum' ? s.equityInvested : s.equityPeriodic, color: '#0F3D3E', show: true },\n  ];\n  buckets.forEach(b => {\n    if (!b.show) return;\n    const card = document.createElement('div');\n    card.className = 'alloc-card';\n    card.style.borderTopColor = b.color;\n    card.innerHTML = `<div class=\"alloc-label\">${b.label}</div><div class=\"alloc-amount\">${fmt(b.amt)}</div><div class=\"alloc-sub\">${b.sub}</div>`;\n    allocGrid.appendChild(card);\n  });\n\n  document.getElementById('totalInvestedOut').textContent = fmt(s.totalInvested);\n  document.getElementById('totalGrownOut').textContent = fmt(s.total);\n  const gainPct = s.totalInvested > 0 ? Math.round(((s.total - s.totalInvested) / s.totalInvested) * 100) : 0;\n  document.getElementById('gainBadgeOut').textContent = `+ ${fmt(s.total - s.totalInvested)} in growth (${gainPct}% over what you put in)`;\n\n  const bucketCompareGrid = document.getElementById('bucketCompareGrid');\n  bucketCompareGrid.innerHTML = '';\n  const bcBuckets = [\n    { label: 'SSY', invested: s.ssyInvested, grown: s.ssyFV, color: '#E8A33D', show: s.ssyEligible },\n    { label: 'PPF', invested: s.ppfInvested, grown: s.ppfFV, color: '#4E6C50', show: true },\n    { label: 'Debt funds', invested: s.debtInvested, grown: s.debtFV, color: '#7A6C5D', show: true },\n    { label: 'Equity index', invested: s.equityInvested, grown: s.equityFV, color: '#0F3D3E', show: true },\n  ];\n  bcBuckets.forEach(b => {\n    if (!b.show) return;\n    const card = document.createElement('div');\n    card.className = 'alloc-card';\n    card.style.borderTopColor = b.color;\n    card.innerHTML = `<div class=\"alloc-label\">${b.label}</div><div class=\"invested-tag\">invested ${fmt(b.invested)}</div><div class=\"alloc-amount\">${fmt(b.grown)}</div>`;\n    bucketCompareGrid.appendChild(card);\n  });\n\n  document.getElementById('inflationExplainer').textContent =\n    `${fmt(s.total)} at age ${s.targetAge} won't buy what ${fmt(s.total)} buys today \u2014 at ${state.inflation}% inflation, compounded monthly over ${s.horizon * 12} months, prices roughly ${s.inflationMultiple.toFixed(2)}x by then. Here's the same corpus in today's purchasing power.`;\n  document.getElementById('nominalCorpusOut').textContent = fmt(s.total);\n  document.getElementById('realValueOut').textContent = fmt(s.realValue);\n  document.getElementById('inflationBadgeOut').textContent = `Inflation quietly eats ${fmt(s.purchasingPowerLoss)} of purchasing power \u2014 plan the actual goal (college fees, wedding costs) against the today's-\u20b9 figure, not the nominal one.`;\n\n  document.getElementById('realGainExplainer').textContent =\n    `If this same money had only grown at the ${state.inflation}% inflation rate \u2014 enough to keep up with prices but earn nothing extra \u2014 it would have become ${fmt(s.inflationOnlyFV)}. Your actual plan gets to ${fmt(s.total)}. The difference is what your investing genuinely earned above and beyond inflation, with the time-value-of-money illusion stripped out.`;\n  document.getElementById('inflationOnlyOut').textContent = fmt(s.inflationOnlyFV);\n  document.getElementById('actualPlanOut').textContent = fmt(s.total);\n  document.getElementById('realGainBadgeOut').textContent = `Real earned above inflation: ${fmt(s.realGain)}`;\n\n  const taxGrid = document.getElementById('taxGrid');\n  taxGrid.innerHTML = `\n    <div class=\"alloc-card\"><div class=\"alloc-label\">Equity LTCG tax</div><div class=\"alloc-amount\">${fmt(s.equityTax)}</div><div class=\"alloc-sub\">on ${fmt(s.equityGain)} gain, 12.5% above \u20b91.25L exemption</div></div>\n    <div class=\"alloc-card\"><div class=\"alloc-label\">Debt fund tax</div><div class=\"alloc-amount\">${fmt(s.debtTax)}</div><div class=\"alloc-sub\">on ${fmt(s.debtGain)} gain, taxed fully at ${state.slabRate}% slab</div></div>\n    <div class=\"alloc-card\"><div class=\"alloc-label\">SSY tax</div><div class=\"alloc-amount\">\u20b90</div><div class=\"alloc-sub\">EEE \u2014 fully exempt</div></div>\n    <div class=\"alloc-card\"><div class=\"alloc-label\">PPF tax</div><div class=\"alloc-amount\">\u20b90</div><div class=\"alloc-sub\">EEE \u2014 fully exempt</div></div>\n  `;\n  document.getElementById('beforeTaxOut').textContent = fmt(s.total);\n  document.getElementById('afterTaxLabel').textContent = `After tax (${fmt(s.totalTax)} paid)`;\n  document.getElementById('afterTaxOut').textContent = fmt(s.afterTaxTotal);\n  document.getElementById('afterTaxRealOut').textContent = fmt(s.afterTaxRealValue);\n\n  const ctx = document.getElementById('glideChart').getContext('2d');\n  const labels = s.glide.map(g => `age ${state.age + g.year}`);\n  const equityData = s.glide.map(g => g.equity);\n  const debtData = s.glide.map(g => g.debt);\n  if (glideChartInstance) glideChartInstance.destroy();\n  glideChartInstance = new Chart(ctx, {\n    type: 'line',\n    data: {\n      labels,\n      datasets: [\n        { label: 'Equity', data: equityData, borderColor: '#0F3D3E', backgroundColor: 'rgba(15,61,62,0.35)', fill: true, stepped: 'after', tension: 0 },\n        { label: 'Debt/PPF/SSY', data: debtData, borderColor: '#E8A33D', backgroundColor: 'rgba(232,163,61,0.35)', fill: true, stepped: 'after', tension: 0 },\n      ]\n    },\n    options: {\n      responsive: true,\n      scales: {\n        y: { stacked: true, min: 0, max: 100, ticks: { callback: v => v + '%' } },\n        x: { stacked: true }\n      },\n      plugins: { legend: { position: 'bottom' } }\n    }\n  });\n}\n\n// Event wiring\ndocument.getElementById('age').addEventListener('input', e => { state.age = Number(e.target.value); render(); });\n\ndocument.querySelectorAll('#purposeGroup .pill').forEach(btn => {\n  btn.addEventListener('click', () => {\n    document.querySelectorAll('#purposeGroup .pill').forEach(b => b.classList.remove('active'));\n    btn.classList.add('active');\n    const p = btn.dataset.purpose;\n    if (p === 'custom') {\n      state.useCustom = true;\n      document.getElementById('customTargetRow').style.display = 'block';\n      document.getElementById('purposeNote').style.display = 'none';\n    } else {\n      state.useCustom = false;\n      state.purposeId = p;\n      document.getElementById('customTargetRow').style.display = 'none';\n      document.getElementById('purposeNote').style.display = 'block';\n      document.getElementById('purposeNote').textContent = PURPOSES[p].note;\n    }\n    render();\n  });\n});\ndocument.getElementById('customTarget').addEventListener('input', e => { state.customTarget = Number(e.target.value); render(); });\n\ndocument.getElementById('modeSip').addEventListener('click', () => {\n  state.mode = 'sip';\n  document.getElementById('modeSip').classList.add('active');\n  document.getElementById('modeLumpsum').classList.remove('active');\n  document.getElementById('frequencyRow').style.display = 'block';\n  document.getElementById('lumpsumNote').style.display = 'none';\n  updateAmountLabel();\n  render();\n});\ndocument.getElementById('modeLumpsum').addEventListener('click', () => {\n  state.mode = 'lumpsum';\n  document.getElementById('modeLumpsum').classList.add('active');\n  document.getElementById('modeSip').classList.remove('active');\n  document.getElementById('frequencyRow').style.display = 'none';\n  document.getElementById('lumpsumNote').style.display = 'block';\n  updateAmountLabel();\n  render();\n});\n\ndocument.querySelectorAll('#freqGroup .pill').forEach(btn => {\n  btn.addEventListener('click', () => {\n    document.querySelectorAll('#freqGroup .pill').forEach(b => b.classList.remove('active'));\n    btn.classList.add('active');\n    state.frequency = btn.dataset.freq;\n    state.periodsPerYear = Number(btn.dataset.ppy);\n    updateAmountLabel();\n    render();\n  });\n});\n\nfunction updateAmountLabel() {\n  const freqLabelMap = { monthly: 'Monthly', quarterly: 'Quarterly', halfyearly: 'Half-Yearly', yearly: 'Yearly' };\n  if (state.mode === 'lumpsum') {\n    document.getElementById('amountLabel').textContent = 'Lump sum amount';\n    document.getElementById('amountSuffix').textContent = 'one-time';\n  } else {\n    document.getElementById('amountLabel').textContent = `${freqLabelMap[state.frequency]} amount`;\n    document.getElementById('amountSuffix').textContent = `/ ${freqLabelMap[state.frequency].toLowerCase()}`;\n  }\n}\n\ndocument.getElementById('amount').addEventListener('input', e => { state.amount = Number(e.target.value); render(); });\ndocument.getElementById('inflation').addEventListener('input', e => {\n  state.inflation = Number(e.target.value);\n  document.getElementById('inflationVal').textContent = state.inflation + '%';\n  render();\n});\ndocument.querySelectorAll('#slabGroup .pill').forEach(btn => {\n  btn.addEventListener('click', () => {\n    document.querySelectorAll('#slabGroup .pill').forEach(b => b.classList.remove('active'));\n    btn.classList.add('active');\n    state.slabRate = Number(btn.dataset.slab);\n    render();\n  });\n});\n\nrender();\n</script>\n</body>\n</html>\n";
